bicepWiring.topic:
resource eventGridTopic 'Microsoft.EventGrid/topics@2024-06-01-preview' = {
  name: topicName
  location: location
  properties: {
    inputSchema: 'CloudEventSchemaV1_0'
    disableLocalAuth: true
  }
  identity: { type: 'SystemAssigned' }
}

bicepWiring.subscription:
resource eventSubscription 'Microsoft.EventGrid/topics/eventSubscriptions@2024-06-01-preview' = {
  parent: eventGridTopic
  name: subscriptionName
  properties: {
    destination: {
      endpointType: 'WebHook'
      properties: { endpointUrl: endpointUrl }
    }
    filter: { enableAdvancedFilteringOnArrays: true }
    eventDeliverySchema: 'CloudEventSchemaV1_0'
  }
}

sdkInitPattern.typescript:
import { EventGridPublisherClient } from '@azure/eventgrid';
import { DefaultAzureCredential } from '@azure/identity';

const credential = new DefaultAzureCredential();
const client = new EventGridPublisherClient(
  process.env.AZURE_EVENT_GRID_TOPIC_ENDPOINT!,
  'CloudEvent',
  credential
);

await client.send([{
  type: 'com.myapp.order.created',
  source: '/orders',
  data: { orderId: '123', amount: 99.99 }
}]);

receiverPattern.webhookValidation:
# CloudEvents spec — respond to OPTIONS with WebHook-Allowed-Origin header
@app.options('/events')
def validate_webhook():
    origin = request.headers.get('WebHook-Request-Origin')
    return '', 200, {'WebHook-Allowed-Origin': origin}
